import 'package:shared_preferences/shared_preferences.dart';
import '../models/user_prefs.dart';
class PrefsService {static const _city='city',_level='level',_local='local',_logged='logged',_welcomed='welcomed',_pantry='pantry',_favorites='favorites'; static Future<UserPrefs> load() async {final p=await SharedPreferences.getInstance();return UserPrefs(city:p.getString(_city)??'تهران',level:p.getString(_level)??'روزمره',showLocalFirst:p.getBool(_local)??true,loggedIn:p.getBool(_logged)??false,welcomed:p.getBool(_welcomed)??false,pantry:p.getStringList(_pantry)??[],favorites:p.getStringList(_favorites)??[]);} static Future<void> save(UserPrefs u) async {final p=await SharedPreferences.getInstance();await p.setString(_city,u.city);await p.setString(_level,u.level);await p.setBool(_local,u.showLocalFirst);await p.setBool(_logged,u.loggedIn);await p.setBool(_welcomed,u.welcomed);await p.setStringList(_pantry,u.pantry);await p.setStringList(_favorites,u.favorites);}}
